"""L200 lesson 8 (python broker.py): a tiny at-least-once broker over HTTP. /receive hides a message for a
visibility timeout, /ack deletes it, no ack = redelivery, too many receives = dead-letter queue (DLQ).
Two consumers crash mid-work (seeded); the ledger shows the duplicates at-least-once delivery creates."""
import random, threading

from helpers import QuietHandler, SimClock, call, serve

VISIBILITY, MAX_RECEIVES = 3.0, 3  # hide a received message for 3 s; dead-letter after 3 unacked receives


class Broker(QuietHandler):
    clock, lock, queue, dlq, seq = SimClock(), threading.Lock(), [], [], 0

    @classmethod
    def reset(cls, clock):
        cls.clock, cls.queue, cls.dlq, cls.seq = clock, [], [], 0

    def do_POST(self):
        req, cls, now = self.read_json(), type(self), self.clock()
        with self.lock:
            if self.path == "/send":
                cls.seq += 1
                cls.queue.append({"id": f"m{cls.seq}", "body": req["body"], "visible_at": now, "receives": 0})
                return self.reply(200, {"id": f"m{cls.seq}"})
            if self.path == "/receive":
                for m in list(cls.queue):
                    if m["visible_at"] > now:  # in flight: invisible until its visibility timeout ends
                        continue
                    if m["receives"] >= MAX_RECEIVES:  # poison: received N times, never acked -> DLQ
                        cls.queue.remove(m)
                        cls.dlq.append(m)
                        continue
                    m["receives"] += 1
                    m["visible_at"] = now + VISIBILITY  # lease on the message, not a delete
                    m["receipt"] = f"{m['id']}#{m['receives']}"  # new receipt for every delivery
                    return self.reply(200, {k: m[k] for k in ("id", "body", "receipt", "receives")})
                return self.reply(404, {"empty": True, "in_flight": len(cls.queue)})
            m = next((m for m in cls.queue if m.get("receipt") == req["receipt"]), None)
            if m is None:  # /ack with an old receipt: the message was redelivered (or already acked)
                return self.reply(409, {"error": "stale receipt"})
            cls.queue.remove(m)  # ack = done: delete for good
            self.reply(200, {"acked": m["id"]})


def consume(name, url, rng, ledger, log, crash_rate):
    status, msg, _ = call(url + "/receive", {})
    if status != 200:
        return
    if msg["body"] == "poison":  # a payload the handler can never process: it crashes every time
        return log(f"{name} {msg['id']}={msg['body']} receive #{msg['receives']}: CRASHED while parsing")
    ledger.append((msg["id"], msg["body"]))  # the side effect (e.g. charge a card) happens first ...
    if rng.random() < crash_rate:  # ... then the consumer crashes mid-work: no ack -> redelivery later
        return log(f"{name} {msg['id']}={msg['body']} receive #{msg['receives']}: charged, CRASHED before ack")
    call(url + "/ack", {"receipt": msg["receipt"]})
    log(f"{name} {msg['id']}={msg['body']} receive #{msg['receives']}: charged, acked")


def run(bodies=("o1", "o2", "o3", "o4", "o5", "o6", "poison"), crash_rate=0.3, seed=9, quiet=False):
    clock, ledger, rng, lines = SimClock(), [], random.Random(seed), []
    Broker.reset(clock)
    srv = serve(Broker)
    url = f"http://127.0.0.1:{srv.server_port}"
    for body in bodies:
        call(url + "/send", {"body": body})
    while Broker.queue and clock() < 60:  # one tick = 1 simulated second
        for name in ("c1", "c2"):
            consume(name, url, rng, ledger, lambda s: lines.append(f"t={clock():.0f} {s}"), crash_rate)
        clock.advance(1.0)
    srv.shutdown()
    srv.server_close()
    if not quiet:
        print("\n".join(lines))
    return {"log": lines, "ledger": ledger, "dlq": [m["body"] for m in Broker.dlq]}


if __name__ == "__main__":
    out = run()
    ids = [i for i, _ in out["ledger"]]
    print(f"ledger: {len(ids)} charges for {len(set(ids))} orders -> {len(ids) - len(set(ids))} duplicates")
    print("dead-letter queue:", out["dlq"])

"""L200 lesson 9 (python ring.py): shard keys over nodes with a consistent-hash ring + virtual nodes.
Measures how many keys move when a node joins or leaves (ring vs hash % N), how even the load is with
1 / 10 / 100 vnodes per node, and what one hot key does to its shard. Deterministic (md5, seeded traffic)."""
import bisect, hashlib, random
from collections import Counter


def h(text):  # stable 64-bit ring position; Python's hash() is salted per process -> never use it here
    return int.from_bytes(hashlib.md5(text.encode("utf-8")).digest()[:8], "big")


class HashRing:
    def __init__(self, nodes, vnodes=100):
        self.vnodes, self.points, self.owner = vnodes, [], {}
        for node in nodes:
            self.add(node)

    def add(self, node):  # virtual nodes: each physical node takes `vnodes` positions on the ring
        for i in range(self.vnodes):
            point = h(f"{node}#{i}")
            bisect.insort(self.points, point)
            self.owner[point] = node

    def remove(self, node):
        self.points = [p for p in self.points if self.owner[p] != node]
        self.owner = {p: n for p, n in self.owner.items() if n != node}

    def node_for(self, key):  # walk clockwise from the key's position to the next vnode (wrap at the end)
        i = bisect.bisect(self.points, h(key)) % len(self.points)
        return self.owner[self.points[i]]


def modulo_node(key, nodes):  # the naive way: hash mod N -> almost every key moves when N changes
    return nodes[h(key) % len(nodes)]


def moved(before, after, keys):
    return sum(before(k) != after(k) for k in keys) / len(keys)


def imbalance(counts):  # busiest node / average node; 1.00 = perfectly even
    return max(counts.values()) / (sum(counts.values()) / len(counts))


def main():
    keys, four = [f"user:{i}" for i in range(10_000)], ["A", "B", "C", "D"]
    ring = HashRing(four)
    grown = HashRing(four + ["E"])
    print(f"add E   : hash % N moves {moved(lambda k: modulo_node(k, four), lambda k: modulo_node(k, four + ['E']), keys):.1%}"
          f" of 10,000 keys; ring moves {moved(ring.node_for, grown.node_for, keys):.1%} (ideal 1/5 = 20.0%)")
    shrunk = HashRing(four)
    shrunk.remove("D")
    only_d = all(ring.node_for(k) == "D" for k in keys if ring.node_for(k) != shrunk.node_for(k))
    print(f"remove D: ring moves {moved(ring.node_for, shrunk.node_for, keys):.1%}; only D's keys moved: {only_d}")
    for v in (1, 10, 100):
        sized = HashRing(four, v)
        counts = Counter(sized.node_for(k) for k in keys)
        print(f"vnodes={v:<3}: keys per node {dict(sorted(counts.items()))} imbalance {imbalance(counts):.2f}")
    rng = random.Random(42)  # 100,000 requests: 20% for one celebrity key, the rest spread evenly
    traffic = Counter(ring.node_for("user:42" if rng.random() < 0.2 else rng.choice(keys)) for _ in range(100_000))
    print(f"hot key : user:42 lives on {ring.node_for('user:42')}; requests per node {dict(sorted(traffic.items()))}"
          f" imbalance {imbalance(traffic):.2f}")


if __name__ == "__main__":
    main()

"""L200 lesson 11 (python ratelimit.py): per-client token buckets in an HTTP API. Over the limit the server
answers 429 Too Many Requests + Retry-After (RFC 6585 / RFC 9110). A polite client waits as told, a naive
one retries every 0.1 s, a quiet one is never affected. Simulated clock: identical output on every run."""
import math
from email.utils import parsedate_to_datetime

from helpers import QuietHandler, SimClock, call, serve

RATE, BURST = 2.0, 5  # per client: 2 requests/s on average, bursts of up to 5


class TokenBucket:
    def __init__(self, rate, burst, clock):
        self.rate, self.burst, self.clock = rate, burst, clock
        self.tokens, self.last = float(burst), clock()

    def allow(self):  # returns (allowed, seconds until a token is available)
        now = self.clock()
        self.tokens = min(self.burst, self.tokens + (now - self.last) * self.rate)  # refill for elapsed time
        self.last = now
        if self.tokens >= 1:
            self.tokens -= 1
            return True, 0.0
        return False, (1 - self.tokens) / self.rate


class Api(QuietHandler):
    clock, limiters, make_limiter = SimClock(), {}, None

    def do_GET(self):
        client = self.headers.get("X-Client-Id", self.client_address[0])  # per-client limit key
        limiter = self.limiters.setdefault(client, (type(self).make_limiter or default_limiter)(self.clock))
        ok, wait = limiter.allow()
        if ok:
            return self.reply(200, {"ok": True})
        # 429 + Retry-After in whole seconds (delay-seconds form), rounded UP so an early retry can't fail
        self.reply(429, {"error": "too many requests"}, {"Retry-After": str(max(1, math.ceil(wait)))})


def default_limiter(clock):
    return TokenBucket(RATE, BURST, clock)


def retry_after_seconds(value, now_epoch=0.0):  # RFC 9110 allows delay-seconds OR an HTTP-date
    if value.strip().isdigit():
        return int(value)
    return max(0.0, parsedate_to_datetime(value).timestamp() - now_epoch)


def run(clients, make_limiter=None):
    """clients: {name: (requests_wanted, honor_retry_after)}. Event loop on a simulated clock."""
    clock = SimClock()
    Api.clock, Api.limiters, Api.make_limiter = clock, {}, make_limiter
    srv = serve(Api)
    url = f"http://127.0.0.1:{srv.server_port}/data"
    state = {n: {"next": 0.0, "ok": 0, "429": 0, "trace": [], "want": w, "honor": h} for n, (w, h) in clients.items()}
    while active := [n for n, s in state.items() if s["ok"] < s["want"]]:
        name = min(active, key=lambda n: (state[n]["next"], n))  # next event in time order
        s = state[name]
        clock.t = s["next"]
        status, _, headers = call(url, headers={"X-Client-Id": name})
        if status == 200:
            s["ok"] += 1
            s["trace"].append("200")
            s["done"] = clock.t
        else:
            s["429"] += 1
            wait = retry_after_seconds(headers["Retry-After"]) if s["honor"] else 0.1  # naive: hammer again
            s["trace"].append(f"429(wait {wait:g})")
            s["next"] = round(clock.t + wait, 3)
    srv.shutdown()
    srv.server_close()
    return state


if __name__ == "__main__":
    out = run({"alice": (12, True), "bob": (12, False), "carol": (3, True)})
    print("alice trace:", " ".join(out["alice"]["trace"]))
    for name, s in out.items():
        print(f"{name:<5} ({'honors Retry-After' if s['honor'] else 'retries every 0.1 s'}): "
              f"{s['ok']} ok, {s['429']} x 429, done at t={s['done']:g}s")
